// Enrich ministers_meetings rows with a one-line factual description of
// each organisation, generated by Claude Haiku 4.5 and cached by org name.
//
// Cost-shape: a single Haiku call per UNIQUE organisation, not per row.
// Many ministers meet the same org (e.g. "Mayor of London" appears in
// dozens of rows), so the cache cuts the API spend ~10x vs per-row.
//
// Pipeline:
//   1. SELECT distinct organisation FROM ministers_meetings
//      WHERE organisation IS NOT NULL AND enriched_description IS NULL
//   2. For each unique org → one Haiku call
//   3. UPDATE ministers_meetings SET enriched_description = ?
//      WHERE organisation = ?
//   4. 300ms delay between API calls; rows whose enriched_description
//      already exists are skipped, so re-runs are idempotent.
//
// Pre-req: ministers_meetings must have an `enriched_description text`
// column (added manually via Supabase Studio).
const Anthropic = require('@anthropic-ai/sdk').default;
const { createClient } = require('@supabase/supabase-js');

const SUPABASE_URL = 'https://nwnsvnbudmfkhhwcjwwr.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Im53bnN2bmJ1ZG1ma2hod2Nqd3dyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzM4NTkyNTUsImV4cCI6MjA4OTQzNTI1NX0.8PW8OHPr08zcXy-tGq0R9O04ZmKwt9twfnmagClDnuw';
const supabase = createClient(SUPABASE_URL, SUPABASE_KEY);

const DELAY_MS = 300;
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

const SYSTEM = 'Describe this UK organisation in one factual sentence. State what it does and what sector it operates in. No speculation. No commentary. Facts only. Maximum 25 words.';

const MODEL = 'claude-haiku-4-5-20251001';
const MAX_TOKENS = 80;

const client = process.env.ANTHROPIC_API_KEY ? new Anthropic() : null;

// Pull all rows still missing a description; collect distinct
// organisations with their occurrence count (purely informational).
async function fetchOrgsToEnrich() {
  const { data, error } = await supabase
    .from('ministers_meetings')
    .select('organisation')
    .is('enriched_description', null)
    .not('organisation', 'is', null)
    .limit(10000);
  if (error) {
    console.error('[enrich] fetch error:', error.message || error);
    return [];
  }
  const counts = new Map();
  for (const r of data || []) {
    const name = String(r.organisation || '').trim();
    if (!name) continue;
    counts.set(name, (counts.get(name) || 0) + 1);
  }
  return Array.from(counts.entries()).map(([name, count]) => ({ name, count }));
}

async function describeOrg(name) {
  if (!client) throw new Error('ANTHROPIC_API_KEY not set');
  const resp = await client.messages.create({
    model: MODEL,
    max_tokens: MAX_TOKENS,
    system: SYSTEM,
    messages: [{ role: 'user', content: name }],
  });
  const block = resp.content[0];
  const text = block?.type === 'text' ? block.text.trim() : '';
  return {
    text,
    inputTokens: resp.usage?.input_tokens ?? 0,
    outputTokens: resp.usage?.output_tokens ?? 0,
  };
}

async function applyDescription(name, description) {
  const { error, count } = await supabase
    .from('ministers_meetings')
    .update({ enriched_description: description }, { count: 'exact' })
    .eq('organisation', name)
    .is('enriched_description', null);
  if (error) {
    console.error(`[enrich] update error for "${name}": ${error.message || error}`);
    return 0;
  }
  return count ?? 0;
}

// Haiku 4.5 pricing per 1M tokens: $1 input, $5 output.
function priceUsd(input, output) {
  return (input * 1) / 1_000_000 + (output * 5) / 1_000_000;
}

async function main() {
  if (!client) {
    console.error('[enrich] ANTHROPIC_API_KEY not set — cannot enrich. Exiting.');
    process.exit(0);
  }
  console.log('[enrich] fetching organisations needing enrichment…');
  const orgs = await fetchOrgsToEnrich();
  console.log(`[enrich] ${orgs.length} unique organisations to enrich`);
  if (orgs.length === 0) { console.log('[enrich] nothing to do'); return; }

  // Largest organisations first — cheaper to fail on a small one than
  // to have a big one fall through.
  orgs.sort((a, b) => b.count - a.count);

  let totalIn = 0, totalOut = 0, succeeded = 0, rowsUpdated = 0;
  for (let i = 0; i < orgs.length; i++) {
    const o = orgs[i];
    try {
      const { text, inputTokens, outputTokens } = await describeOrg(o.name);
      totalIn += inputTokens;
      totalOut += outputTokens;
      if (!text) {
        console.error(`  [${i + 1}/${orgs.length}] EMPTY response for "${o.name.slice(0, 60)}"`);
        await sleep(DELAY_MS);
        continue;
      }
      const updated = await applyDescription(o.name, text);
      succeeded++;
      rowsUpdated += updated;
      if (i < 5 || i % 25 === 0) {
        console.log(`  [${i + 1}/${orgs.length}] (×${o.count}) ${o.name.slice(0, 60)}`);
        console.log(`        → ${text.slice(0, 110)}`);
      }
    } catch (e) {
      console.error(`  [${i + 1}/${orgs.length}] error for "${o.name.slice(0, 60)}": ${e.message || e}`);
    }
    await sleep(DELAY_MS);
  }

  console.log('');
  console.log(`[enrich] organisations enriched: ${succeeded} / ${orgs.length}`);
  console.log(`[enrich] rows updated:           ${rowsUpdated}`);
  console.log(`[enrich] tokens — in: ${totalIn.toLocaleString()}, out: ${totalOut.toLocaleString()}`);
  console.log(`[enrich] estimated cost:         $${priceUsd(totalIn, totalOut).toFixed(4)}`);
}

main().catch((e) => { console.error('[enrich] fatal:', e?.message || e); process.exit(0); });
